#!/usr/bin/env bash
#
# ТЕЛО ГЕНЕРАТОРА ПРОИЗВОДНЫХ ПОЧТЫ — ОНО ЖИВЁТ ЗДЕСЬ, А НЕ В ВОРКФЛОУ
# (тред 075-comms-derived-window-reddens-main, решение john 2026-09-02).
#
# Почему вынесено. `comms-derived.yml` на событии `push` исполняется из версии
# файла В ВЕТКЕ `comms`, поэтому копия обязана лежать там и обязана совпадать с
# каноном в `main` байт-в-байт (шаг «comms-derived синхронен с каноном» в
# `checks.yml`). Копию кладут ДО merge'а канона — иначе первое же событие
# поедет по устаревшему коду, — и между «копия легла» и «канон влит» открыто
# окно, в котором КАЖДЫЙ push в `main` красен по чужой причине. Пока в копии
# лежала ЛОГИКА, окно открывалось на каждую правку логики: 02.09 расхождением
# были четыре комментария, и такт ушёл на разведение красноты (прогон
# 33625904628, красен только шаг 11).
#
# Чинится не проверка и не порядок, а то, ЧТО лежит в копии: тело переехало
# сюда, в `main`, а в ветке `comms` осталась обёртка, которая его зовёт. Этот
# файл читается из чекаута `main` (`.code`), который воркфлоу делает вторым
# шагом, — значит правка логики вступает в силу МЕРЖЕМ и копии не касается.
# Окно не прощено и не смягчено: порождать его больше нечему.
#
# То же место и по той же причине, что общая дверь push'а (`comms-push.sh`,
# тред 042): логика вне `workflows/**` попадает под круг ревью, тогда как гард
# claude-code-action пропускает ревью на PR, где файл воркфлоу отличается от
# версии дефолтной ветки.
#
# ИСПОЛЬЗОВАНИЕ (единственный вызывающий — `.github/workflows/comms-derived.yml`
# в ветке `comms`):
#   MAIL=<чекаут ветки comms> CODE=<чекаут main> \
#     bash "${GITHUB_WORKSPACE}/.code/.github/scripts/comms-derive.sh"
#
# Обязательные переменные окружения:
#   MAIL — рабочее дерево ветки `comms` (корень workspace, внутри `agent-comms/`);
#   CODE — чекаут `main` с установленными зависимостями (`.code`).
# Рабочая директория на входе — корень чекаута `comms`: коммит и push идут
# оттуда, pathspec `agent-comms` считается от неё.

set -euo pipefail

: "${MAIL:?comms-derive: не названа переменная MAIL (чекаут ветки comms)}"
: "${CODE:?comms-derive: не названа переменная CODE (чекаут main с зависимостями)}"


# ОТКАЗ `derive` НЕ ОБРЫВАЕТ ШАГ, А ДОНОСИТСЯ ДО ЕГО КОНЦА (тред 060).
# Класс, ради которого это стоит: один каталог треда без `_meta.md`
# (так пишет чатный исполнитель, кладущий файлы напрямую) даёт код 2 —
# и пока `run_derive` вызывался голым под `set -e`, шаг умирал на
# первой же команде. Собранные производные ВСЕХ остальных тредов
# оставались в workspace и до коммита не доезжали: 29.08 так встали
# `INDEX.md`, `TASKS.md` и все `_thread.md` обоих контуров десять
# прогонов подряд, 30.08 — ещё два. С #154 команда пишет всё, что
# прочиталось, и отказывает ПОСЛЕДНИМ, после записи, — значит файлы на
# диске к этому моменту есть, и единственное, что мешало их
# закоммитить, — этот обрыв.
#
# Fail-closed НЕ отменяется и подменой кода на 0 здесь не пахнет: код
# `derive` доносится переменной и становится кодом ВСЕГО шага в
# `finish` — прогон остаётся красным, нечитаемый тред остаётся названным
# (строкой отказа и строкой-маркером в `INDEX.md`). Меняется ровно одно:
# красный прогон теперь оставляет после себя запушенные производные, а
# не пустую ветку.
derive_rc=0

# `derive --write` пересобирает _thread.md мигрированных + INDEX.
# Конфиг протокола читается из main через git в .code (репо кода).
run_derive() {
  derive_rc=0
  (cd "$CODE" && pnpm -F agent-protocol --silent cli derive \
    --root "$MAIL" --repo "$CODE" --ref origin/main --write) || derive_rc=$?
}

# ЕДИНСТВЕННАЯ ДВЕРЬ ВЫХОДА С КОДОМ `derive`, и красный из неё не
# выходит немым: без этой строки поле увидело бы зелёный push
# производных и красный шаг без объяснения, почему он красный при
# успешно сделанной работе.
finish() {
  if [ "$derive_rc" -ne 0 ]; then
    echo "::error::производные собраны, записаны и (при расхождении) запушены, НО derive отказал кодом ${derive_rc}: нечитаемый тред назван строкой отказа выше и строкой-маркером в INDEX.md. Прогон красный намеренно — почини названный каталог (тред 060)."
  fi
  exit "$derive_rc"
}

run_derive

# Идемпотентность: расхождения нет — писать нечего, выходим тихо.
#
# ПРОВЕРКА ОБЯЗАНА ВИДЕТЬ НЕОТСЛЕЖИВАЕМОЕ (тред 005). Здесь стоял
# `git diff --quiet`, который сравнивает индекс с рабочим деревом и
# новых файлов не видит ВОВСЕ. На почте, где производных ещё нет,
# `derive --write` создаёт `INDEX.md`, `TASKS.md` и `_thread.md`
# ВПЕРВЫЕ — они неотслеживаемые, дифф пуст, ранний выход срабатывает,
# джоба зеленеет и не производит ничего. Замерено в этом репозитории:
# пять `success` подряд (10:41…11:53Z 2026-08-18) при полном отсутствии
# `INDEX.md` в ветке; воспроизведено на клоне — 8 файлов собрано,
# `git diff --quiet` молчит, `git status --porcelain` называет все восемь.
# В LLE дефект спал, потому что там эти файлы уже отслеживаются —
# то есть просыпается он ровно на пустой почте нового репозитория.
#
# `--porcelain` со скобкой `-- agent-comms` — не украшение: рядом в
# workspace лежит неотслеживаемый чекаут `.code`, и без pathspec он
# один делал бы проверку вечно «грязной».
#
# Прежний комментарий объяснял это место «мягким переходом» — мол,
# пока роль сама прогоняет rebuild, здесь всегда пусто. Само решение о
# мягком переходе в силе (шапка файла), но МОЛЧАЛ генератор не поэтому,
# и объяснение, оправдывающее дефект, хуже отсутствующего.
#
# ВЫХОД ЗДЕСЬ — `finish`, а не `exit 0`, и это не единообразие ради
# единообразия: второй прогон на непочиненной почте идемпотентен (та же
# строка-маркер уже в `INDEX.md`), расхождения нет, и «тихий зелёный»
# погасил бы отказ ровно там, где он ещё верен.
if [ -z "$(git status --porcelain -- agent-comms)" ]; then
  echo "производные уже актуальны — коммитить нечего."
  finish
fi

git config user.name "github-actions[bot]"
git config user.email "41898282+github-actions[bot]@users.noreply.github.com"

# Дверь push'а — общая на всех писателей контура (тред 042): она же
# объявляет потолок попыток, она же различает гонку и отказ сервера и
# выжидает паузу там, где ждать и есть лекарство. Пятый писатель
# переводится на неё ПОСЛЕДНИМ и отдельно от четверых: он исполняется
# из ветки `comms`, поэтому его копия там обязана совпадать с этим
# каноном байт-в-байт, а копия подключает дверь `source`'ом из
# чекаута main — до её merge'а файла там не было вовсе.
#
# Пересборка производных ПОВЕРХ свежего origin/comms остаётся ровно
# там, где была, и лечит ровно гонку: источник (messages/) чужой роли
# уже в ветке, переносить старые производные нельзя. Отказу сервера
# она безразлична — на неподвижной голове это no-op, дающий тот же
# дифф, и цену повтора платит пауза внутри двери, а не этот цикл.
source "${CODE}/.github/scripts/comms-push.sh"
for attempt in $(seq 1 "$COMMS_PUSH_ATTEMPTS"); do
  git add agent-comms
  git commit -m "chore(comms): rebuild derived"
  if comms_push "$attempt"; then
    echo "производные пересобраны и запушены (попытка ${attempt})."
    finish
  fi
  git reset --soft HEAD~1
  git fetch --no-tags origin comms
  git reset --hard origin/comms
  # Пересборка поверх ЧУЖОЙ головы заново меряет и `derive_rc`
  # (функция обнуляет его сама): чужой push мог как положить
  # недостающий `_meta.md`, так и завести новый безголовый каталог, и
  # код обязан говорить о той почте, которая уедет в ветку, а не о той,
  # что была до fetch'а.
  run_derive
  # Тот же вопрос, что и у раннего выхода, — и тот же ответ: после
  # `reset --hard origin/comms` собранные файлы снова не отслеживаются
  # (в голове ветки их нет), так что `git diff` и здесь звал бы «чисто»
  # на непустой работе. Выход тише раннего, цена та же (тред 005, п.2).
  [ -z "$(git status --porcelain -- agent-comms)" ] && { echo "после чужого push расхождений нет."; finish; }
done

# Провал ОБЯЗАН быть заметным (требование заметности из 014): молча
# разошедшиеся производные — тот же класс, что потерянный дубль
# вердикта. Красный job виден без ручной сверки.
#
# Выход ЗДЕСЬ — не `finish`: исчерпанный потолок push'ей — своя
# поломка, и она старше отказа `derive`. Код 1 против кода 2 различает
# их в списке прогонов, а причина названа строкой выше; если при этом
# отказал и `derive`, его собственная строка тоже напечатана — выше, из
# самой команды.
echo "::error::не удалось запушить производные за ${COMMS_PUSH_ATTEMPTS} попыток."
exit 1

